// src/components/Dashboard/ReleaseView/ReleaseQEHome.js
import React, { useEffect, useMemo, useState } from 'react';

/**
 * [PH1-LOCAL] Local-first embed for Excel "Daily Dashboard".
 * 1) Try local:  /files/TQI CBPT Releases DSR as of Oct 08.xlsm
 *    -> Office Web Viewer (generally read-only for local; good for preview)
 * 2) Fallback: SharePoint direct file URL with action=edit (true edit & save)
 *
 * TIP: Set REACT_APP_SP_DSR_URL to the direct workbook URL for best results.
 */
export default function ReleaseQEHome({ release }) {
  const [embedSrc, setEmbedSrc] = useState('');
  const [using, setUsing] = useState('local'); // 'local' | 'sharepoint'
  const sheetHint = 'ActiveCell=Daily%20Dashboard!A1';

  // Local Excel path (served from frontend/public/files)
  const localUrl = useMemo(() => {
    const fname = 'TQI CBPT Releases DSR as of Oct 08.xlsm';
    return `${window.location.origin}/files/${encodeURIComponent(fname)}`;
  }, []);

  // SharePoint direct file URL (env recommended)
  const spBase =
    process.env.REACT_APP_SP_DSR_URL ||
    // Note: this is a library view URL—replace with the workbook's direct link when available
    'https://cibc.sharepoint.com/sites/GRP-PBPTQAReleaseManagement/Shared%20Documents/Forms/AllItems.aspx?id=%2Fsites%2FGRP%2DPBPTQAReleaseManagement%2FShared%20Documents%2FLending%20and%20Deposit%20DSR';

  const spEmbed = useMemo(() => {
    const sep = spBase.includes('?') ? '&' : '?';
    // Prefer edit; if tenant disallows edit-in-iframe, switch to action=embedview
    return `${spBase}${sep}action=edit&web=1&wdAllowInteractivity=True&${sheetHint}`; // [PH1-LOCAL]
  }, [spBase]);

  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        // [PH1-LOCAL] Probe local file first
        const resp = await fetch(localUrl, { method: 'HEAD', cache: 'no-cache' });
        if (!resp.ok) throw new Error(`Local file not reachable: ${resp.status}`);
        // Local preview via Office viewer (read-only for local files)
        const officeLocal = `https://view.officeapps.live.com/op/embed.aspx?src=${encodeURIComponent(localUrl)}&${sheetHint}`;
        if (!cancelled) {
          setUsing('local');
          setEmbedSrc(officeLocal);
        }
      } catch {
        // Fallback to SharePoint (edit mode)
        if (!cancelled) {
          setUsing('sharepoint');
          setEmbedSrc(spEmbed);
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [localUrl, spEmbed]);

  return (
    <div>
      <div className="muted" style={{ marginBottom: 8 }}>
        Release QE Home for <b>{release || '—'}</b> <span style={{ opacity: 0.7 }}>
          ({using === 'local' ? 'local preview' : 'SharePoint edit'})
        </span>
      </div>
      <div style={{ height: '78vh', borderRadius: 12, overflow: 'hidden', background: '#0f162a' }}>
        <iframe
          title={`TQI CBPT Releases DSR — Daily Dashboard (${using})`}
          src={embedSrc}
          style={{ width: '100%', height: '100%', border: 0 }}
          allow="clipboard-read; clipboard-write; fullscreen"
          allowFullScreen
        />
      </div>
    </div>
  );
}
